use builtin::*;
use vstd::prelude::*;


/// Returns the index of a minimum element in the slice `a`
/// among all elements from index `i` (inclusive) to the end.
/// 
/// # Panics
/// 
/// Panics if `i >= a.len()`.
#[requires(i < a.len())]
#[ensures(i <= result && result < a.len())]
#[ensures(forall(|k: usize| i <= k && k < a.len() ==> a[result] <= a[k]))]
pub fn look_for_min(a: &[i32], i: usize) -> usize {
    // runtime check, preserved for panicking behavior
    assert!(i < a.len(), "start index out of bounds");

    let mut min_index = i;

    // We iterate j from i+1 up to a.len(), maintaining:
    //   1) i+1 <= j <= a.len()
    //   2) i <= min_index < j
    //   3) for all k in [i, j), a[min_index] <= a[k]
    // and we use a.len() - j as a decreasing measure.
    #[invariant(i + 1 <= j && j <= a.len())]
    #[invariant(i <= min_index && min_index < j)]
    #[invariant(forall(|k: usize| i <= k && k < j ==> a[min_index] <= a[k]))]
    #[decreases(a.len() - j)]
    for j in (i + 1)..a.len() {
        if a[j] < a[min_index] {
            min_index = j;
        }
    }

    min_index
}


